package de.fitnesscoach.agent;

import org.json.JSONArray;import org.json.JSONException;import org.json.JSONObject;import java.time.*;import java.util.*;import de.fitnesscoach.data.entity.*;import de.fitnesscoach.data.repository.FitnessCoachRepository;import de.fitnesscoach.domain.plan.*;

public final class AgentToolExecutor {
 private static final Set<String> READ=Set.of("get_today_status","get_health_summary","get_training_plan","get_workout_history","get_active_goal","get_baseline","get_progress");private static final Set<String> WRITE=Set.of("modify_workout","reschedule_workout","skip_workout","record_checkin");private final FitnessCoachRepository repo;private final PlanAdaptationPolicy adaptationPolicy=new DefaultPlanAdaptationPolicy();public AgentToolExecutor(FitnessCoachRepository repo){this.repo=repo;}
 public JSONObject execute(String name,JSONObject args){try{validateName(name);return switch(name){case"get_today_status"->today();case"get_health_summary"->healthSummary(args.optInt("days",14));case"get_training_plan"->trainingPlan(args.optString("weekStart",LocalDate.now().with(DayOfWeek.MONDAY).toString()));case"get_workout_history"->workoutHistory(args.optInt("days",28));case"get_active_goal"->activeGoal();case"get_baseline"->baseline(args.getString("metric"),args.getInt("windowDays"));case"get_progress"->progress(args.optInt("days",28));case"modify_workout"->modifyWorkout(args);case"reschedule_workout"->rescheduleWorkout(args);case"skip_workout"->skipWorkout(args);case"record_checkin"->recordCheckin(args);default->throw new IllegalArgumentException("Unbekanntes Tool");};}catch(Exception e){return result(false,"REJECTED",e.getMessage()==null?"Lokale Validierung fehlgeschlagen.":e.getMessage(),null);}}
 private JSONObject today(){LocalDate d=LocalDate.now();JSONObject x=new JSONObject();DailyHealthEntity h=repo.getDailyHealth(d);RecoveryEntity r=repo.getRecovery(d);put(x,"date",d.toString());if(h!=null){put(x,"sleepMinutes",h.sleepMinutes);put(x,"restingHeartRate",h.restingHeartRate);put(x,"steps",h.steps);put(x,"distanceKm",h.distanceKm);}if(r!=null){put(x,"recoveryScore",r.score);put(x,"recoveryConfidence",str(r.confidence));put(x,"recoveryRecommendation",str(r.recommendation));}JSONArray p=new JSONArray();for(PlannedWorkoutEntity w:repo.getPlannedWorkouts(d,d))p.put(planned(w));put(x,"plannedWorkouts",p);return result(true,"OK","Status lokal gelesen.",x);}
 private JSONObject healthSummary(int days){range(days,1,90);JSONArray a=new JSONArray();LocalDate today=LocalDate.now();for(int i=0;i<days;i++){LocalDate d=today.minusDays(i);DailyHealthEntity h=repo.getDailyHealth(d);if(h==null)continue;JSONObject j=new JSONObject();put(j,"date",d.toString());put(j,"sleepMinutes",h.sleepMinutes);put(j,"restingHeartRate",h.restingHeartRate);put(j,"steps",h.steps);put(j,"distanceKm",h.distanceKm);put(j,"exerciseMinutes",h.exerciseMinutes);a.put(j);}JSONObject x=new JSONObject();put(x,"days",days);put(x,"summaries",a);return result(true,"OK","Zusammenfassung lokal gelesen.",x);}
 private JSONObject trainingPlan(String weekStart){LocalDate s=LocalDate.parse(weekStart);JSONArray a=new JSONArray();for(PlannedWorkoutEntity p:repo.getPlannedWorkouts(s,s.plusDays(6)))a.put(planned(p));JSONObject x=new JSONObject();put(x,"weekStart",s.toString());put(x,"workouts",a);return result(true,"OK","Trainingsplan lokal gelesen.",x);}
 private JSONObject workoutHistory(int days){range(days,1,90);Instant from=LocalDate.now().minusDays(days-1).atStartOfDay(ZoneId.systemDefault()).toInstant();JSONArray a=new JSONArray();for(WorkoutEntity w:repo.getWorkouts()){if(w.startTime==null||w.startTime.isBefore(from))continue;JSONObject j=new JSONObject();put(j,"id",w.id);put(j,"date",w.startTime.atZone(ZoneId.systemDefault()).toLocalDate().toString());put(j,"sportType",str(w.sportType));put(j,"workoutType",str(w.workoutType));put(j,"durationMinutes",w.durationMinutes);put(j,"distanceKm",w.distanceKm);put(j,"rpe",w.rpe);a.put(j);if(a.length()>=30)break;}JSONObject x=new JSONObject();put(x,"workouts",a);return result(true,"OK","Trainingshistorie lokal gelesen.",x);}
 private JSONObject activeGoal(){GoalEntity g=repo.getActiveGoal();if(g==null)return result(true,"NO_DATA","Kein aktives Ziel vorhanden.",unavailableData());JSONObject x=new JSONObject();put(x,"type",str(g.type));put(x,"title",g.title);put(x,"targetDate",g.targetDate==null?null:g.targetDate.toString());put(x,"targetValue",g.targetValue);put(x,"targetUnit",g.targetUnit);return result(true,"OK","Aktives Ziel lokal gelesen.",x);}
 private JSONObject baseline(String metric,int window){if(!Set.of("sleepMinutes","restingHeartRate","steps","distanceKm","trainingLoad").contains(metric)||!Set.of(7,28,90).contains(window))throw new IllegalArgumentException("Ungültige Baseline-Anfrage.");BaselineEntity b=repo.getBaseline(metric,window);if(b==null)return result(true,"NO_DATA","Baseline nicht verfügbar.",unavailableData());JSONObject x=new JSONObject();put(x,"metric",metric);put(x,"windowDays",window);put(x,"value",b.value);put(x,"sampleCount",b.sampleCount);put(x,"confidence",str(b.confidence));return result(true,"OK","Baseline lokal gelesen.",x);}
 private JSONObject progress(int days){range(days,7,90);JSONObject x=new JSONObject();put(x,"goal",activeGoal().optJSONObject("data"));put(x,"training",workoutHistory(days).optJSONObject("data"));put(x,"recovery",today().optJSONObject("data"));return result(true,"OK","Fortschritt lokal zusammengefasst.",x);}
 private JSONObject modifyWorkout(JSONObject a)throws JSONException{long id=requiredId(a);PlannedWorkoutEntity w=requiredWorkout(id);String before=snapshot(w);Integer duration=a.has("durationMinutes")?a.getInt("durationMinutes"):w.plannedDurationMinutes;if(duration!=null&&(duration<0||duration>300))throw new IllegalArgumentException("Trainingsdauer außerhalb des erlaubten Bereichs.");DomainEnums.WorkoutType type=w.workoutType;if(a.has("workoutType"))type=DomainEnums.WorkoutType.valueOf(a.getString("workoutType"));if(type==DomainEnums.WorkoutType.REST)duration=0;validateAvailability(w.date,duration);validateNeighbors(w.id,w.date,type);w.plannedDurationMinutes=duration;w.workoutType=type;applyRecoveryPolicy(w,w.date);w.status=DomainEnums.WorkoutStatus.ADAPTED;w.version=Math.max(1,w.version+1);w.updatedAt=Instant.now();repo.updatePlannedWorkout(w);audit(DomainEnums.CoachDecisionType.REPLACE_WORKOUT,w,before,snapshot(w),"AGENT_MODIFY","Vom Coach angeforderte Änderung lokal validiert und durch die PlanAdaptationPolicy geprüft.");return result(true,"APPLIED","Training wurde lokal validiert und geändert.",planned(w));}
 private JSONObject rescheduleWorkout(JSONObject a)throws JSONException{long id=requiredId(a);PlannedWorkoutEntity w=requiredWorkout(id);LocalDate target=LocalDate.parse(a.getString("date"));String before=snapshot(w);validateAvailability(target,w.plannedDurationMinutes);validateNeighbors(w.id,target,w.workoutType);w.date=target;applyRecoveryPolicy(w,target);w.status=DomainEnums.WorkoutStatus.ADAPTED;w.version=Math.max(1,w.version+1);w.updatedAt=Instant.now();repo.updatePlannedWorkout(w);audit(DomainEnums.CoachDecisionType.RESCHEDULE_WORKOUT,w,before,snapshot(w),"AGENT_RESCHEDULE","Verschiebung lokal gegen Verfügbarkeit, Nachbareinheiten und PlanAdaptationPolicy validiert.");return result(true,"APPLIED","Training wurde verschoben.",planned(w));}
 private JSONObject skipWorkout(JSONObject a)throws JSONException{long id=requiredId(a);PlannedWorkoutEntity w=requiredWorkout(id);String before=snapshot(w);w.status=DomainEnums.WorkoutStatus.SKIPPED;w.version=Math.max(1,w.version+1);w.updatedAt=Instant.now();repo.updatePlannedWorkout(w);audit(DomainEnums.CoachDecisionType.CANCEL_WORKOUT,w,before,snapshot(w),"AGENT_SKIP",a.optString("reason","Vom Nutzer übersprungen."));return result(true,"APPLIED","Training wurde als übersprungen markiert.",planned(w));}
 private JSONObject recordCheckin(JSONObject a)throws JSONException{LocalDate d=LocalDate.parse(a.optString("date",LocalDate.now().toString()));CheckInEntity c=repo.getCheckIn(d);if(c==null){c=new CheckInEntity();c.date=d;c.createdAt=Instant.now();}c.energy=optionalRating(a,"energy",c.energy);c.muscleFatigue=optionalRating(a,"muscleFatigue",c.muscleFatigue);c.motivation=optionalRating(a,"motivation",c.motivation);c.stress=optionalRating(a,"stress",c.stress);repo.saveCheckIn(c);JSONObject x=new JSONObject();put(x,"date",d.toString());put(x,"energy",c.energy);put(x,"muscleFatigue",c.muscleFatigue);put(x,"motivation",c.motivation);put(x,"stress",c.stress);return result(true,"APPLIED","Check-in wurde lokal gespeichert.",x);}
 private void applyRecoveryPolicy(PlannedWorkoutEntity w,LocalDate date){PlannedWorkoutEntity prev=null,next=null;for(PlannedWorkoutEntity p:repo.getPlannedWorkouts(date.minusDays(1),date.plusDays(1))){if(p.id==w.id||p.date==null)continue;if(p.date.isBefore(date))prev=p;else if(p.date.isAfter(date))next=p;}RecoveryEntity recovery=repo.getRecovery(date);DomainEnums.RecoveryRecommendation recommendation=recovery==null?DomainEnums.RecoveryRecommendation.UNKNOWN:recovery.recommendation;PlannedWorkoutEntity adapted=adaptationPolicy.adapt(w,recommendation,prev,next);w.sportType=adapted.sportType;w.workoutType=adapted.workoutType;w.title=adapted.title;w.description=adapted.description;w.plannedDurationMinutes=adapted.plannedDurationMinutes;w.plannedDistanceKm=adapted.plannedDistanceKm;w.targetHeartRateMin=adapted.targetHeartRateMin;w.targetHeartRateMax=adapted.targetHeartRateMax;w.targetPaceMinSecKm=adapted.targetPaceMinSecKm;w.targetPaceMaxSecKm=adapted.targetPaceMaxSecKm;}
 private int optionalRating(JSONObject a,String k,Integer old)throws JSONException{if(!a.has(k))return old==null?3:old;int v=a.getInt(k);range(v,1,5);return v;}private long requiredId(JSONObject a)throws JSONException{if(!a.has("workoutId"))throw new IllegalArgumentException("workoutId fehlt.");long id=a.getLong("workoutId");if(id<=0)throw new IllegalArgumentException("Ungültige workoutId.");return id;}private PlannedWorkoutEntity requiredWorkout(long id){PlannedWorkoutEntity w=repo.getPlannedWorkout(id);if(w==null)throw new IllegalArgumentException("Geplantes Training nicht gefunden.");if(w.status==DomainEnums.WorkoutStatus.COMPLETED||w.status==DomainEnums.WorkoutStatus.CANCELLED)throw new IllegalArgumentException("Abgeschlossenes Training kann nicht geändert werden.");return w;}
 private void validateAvailability(LocalDate date,Integer duration){for(TrainingAvailabilityEntity a:repo.getAvailability())if(a.dayOfWeek==date.getDayOfWeek().getValue()){if(!a.available)throw new IllegalArgumentException("Am Zieltag ist kein Training verfügbar.");if(duration!=null&&a.maxDurationMinutes!=null&&duration>a.maxDurationMinutes)throw new IllegalArgumentException("Dauer überschreitet die lokale Tagesverfügbarkeit.");return;}throw new IllegalArgumentException("Für den Zieltag fehlt eine Trainingsverfügbarkeit.");}
 private void validateNeighbors(long id,LocalDate date,DomainEnums.WorkoutType type){if(!high(type))return;for(PlannedWorkoutEntity p:repo.getPlannedWorkouts(date.minusDays(1),date.plusDays(1)))if(p.id!=id&&p.date!=null&&Math.abs(p.date.toEpochDay()-date.toEpochDay())==1&&high(p.workoutType)&&p.status!=DomainEnums.WorkoutStatus.SKIPPED&&p.status!=DomainEnums.WorkoutStatus.CANCELLED)throw new IllegalArgumentException("Intensive Einheiten dürfen nicht direkt aufeinander folgen.");}
 private boolean high(DomainEnums.WorkoutType t){return t==DomainEnums.WorkoutType.INTERVAL||t==DomainEnums.WorkoutType.TEMPO||t==DomainEnums.WorkoutType.LONG;}private void audit(DomainEnums.CoachDecisionType type,PlannedWorkoutEntity w,String before,String after,String code,String reason){CoachDecisionEntity d=new CoachDecisionEntity();d.timestamp=Instant.now();d.decisionType=type;d.targetEntityId=w.id;d.beforeJson=before;d.afterJson=after;d.reasonCode=code;d.reasonText=reason;d.source="AGENT_LOCAL_TOOL";repo.insertDecision(d);}private JSONObject planned(PlannedWorkoutEntity p){JSONObject j=new JSONObject();put(j,"id",p.id);put(j,"date",p.date==null?null:p.date.toString());put(j,"sportType",str(p.sportType));put(j,"workoutType",str(p.workoutType));put(j,"durationMinutes",p.plannedDurationMinutes);put(j,"distanceKm",p.plannedDistanceKm);put(j,"status",str(p.status));put(j,"version",p.version);return j;}private String snapshot(PlannedWorkoutEntity w){return planned(w).toString();}
 private void validateName(String n){if(!READ.contains(n)&&!WRITE.contains(n))throw new IllegalArgumentException("Unbekanntes Tool wurde abgelehnt.");}private void range(int v,int min,int max){if(v<min||v>max)throw new IllegalArgumentException("Argument außerhalb des erlaubten Bereichs.");}private JSONObject result(boolean success,String code,String message,JSONObject data){JSONObject x=new JSONObject();put(x,"success",success);put(x,"code",code);put(x,"message",message);if(data!=null)put(x,"data",data);return x;}private JSONObject unavailableData(){JSONObject x=new JSONObject();put(x,"availability","unavailable");return x;}private static String str(Object x){return x==null?null:x.toString();}private static void put(JSONObject j,String k,Object v){try{j.put(k,v==null?JSONObject.NULL:v);}catch(JSONException e){throw new IllegalStateException("Lokales Agent-Ergebnis konnte nicht als JSON aufgebaut werden.",e);}}
}
